mapper.select:
SELECT o.*, c.name AS customer_name, c.phone AS customer_phone, v.plate_number FROM beauty_orders o LEFT JOIN customers c ON o.customer_id = c.id LEFT JOIN vehicles v ON o.vehicle_id = v.id WHERE o.is_deleted = 0
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND o.customer_id = #{customerId}
AND o.status = #{status}
ORDER BY o.create_time DESC
